let lang=localStorage.getItem('inv_lang')||'en';
const t=k=>I18N[lang][k];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const num=s=>{if(typeof s==='number')return s;const m=String(s||'').replace(/,/g,'').match(/-?\d+(\.\d+)?/);return m?parseFloat(m[0]):null};
const catName=c=>(CATS[c]||{})[lang]||c;
const byKey=k=>DATA.find(x=>x.key===k);
let picked=JSON.parse(localStorage.getItem('inv_picked')||'[]').filter(p=>byKey(p.key));
let moves=[];
let curCat='';
function saveP(){localStorage.setItem('inv_picked',JSON.stringify(picked))}
function saveM(){localStorage.setItem('inv_moves',JSON.stringify(moves))}
function netMove(k){return moves.reduce((s,m)=>m.key===k?s+(m.type==='in'?m.n:-m.n):s,0)}
function stockOf(x){const b=num(x.qty),d=netMove(x.key);if(b===null&&!moves.some(m=>m.key===x.key))return null;return (b||0)+d}
function status(x){const s=stockOf(x);if(s===null){const q=String(x.qty||'').trim();return q&&!['/','0'].includes(q)?'pending':'out'}return s>=50?'ok':s>0?'low':'out'}
const stLabel=s=>t({ok:'stOk',low:'stLow',pending:'stPending',out:'stOut'}[s]);
const inStock=x=>{const s=status(x);return s==='ok'||s==='low'};
const showQty=x=>{const s=stockOf(x);return s===null?(x.qty||''):String(s)};
function match(x,f){if(f==='instock')return inStock(x);if(f==='all')return true;return status(x)===f}
function applyLang(){
  document.documentElement.lang=lang==='en'?'en':'zh-CN';
  document.querySelectorAll('[data-i]').forEach(e=>e.textContent=t(e.dataset.i));
  document.querySelectorAll('[data-ph]').forEach(e=>e.placeholder=t(e.dataset.ph));
  $('#langBtn').textContent=lang==='en'?'中文':'EN';
  renderCats();render();
}
function renderCats(){
  const counts={};DATA.forEach(x=>counts[x.cat]=(counts[x.cat]||0)+1);
  const f=$('#filter').value;const inC={};DATA.filter(x=>match(x,f)).forEach(x=>inC[x.cat]=(inC[x.cat]||0)+1);
  $('#cats').innerHTML=`<button class="chip ${curCat===''?'on':''}" onclick="setCat('')">${t('allCat')} <i>${DATA.filter(x=>match(x,f)).length}</i></button>`+
  Object.keys(CATS).map(c=>`<button class="chip ${curCat===c?'on':''}" onclick="setCat('${esc(c)}')">${esc(catName(c))} <i>${inC[c]||0}</i></button>`).join('');
}
function setCat(c){curCat=c;renderCats();render()}
function render(){
  const q=$('#q').value.toLowerCase().trim(),f=$('#filter').value,sort=$('#sort').value;
  let a=DATA.filter(x=>(!curCat||x.cat===curCat)&&(!q||[x.id,x.qty,x.base,x.size,x.cat,catName(x.cat)].join(' ').toLowerCase().includes(q))&&match(x,f));
  if(sort==='qtydesc')a.sort((m,n)=>(stockOf(n)||0)-(stockOf(m)||0));
  else if(sort==='qtyasc')a.sort((m,n)=>(stockOf(m)||0)-(stockOf(n)||0));
  else a.sort((m,n)=>m.id.localeCompare(n.id,'zh',{numeric:true}));
  $('#count').textContent=a.length;
  $('#grid').innerHTML=a.map(x=>{const p=picked.find(p=>p.key===x.key),st=status(x),s=stockOf(x);
    return `<article class="card ${inStock(x)?'':'dim'}"><div class="pic" onclick="detail('${x.key}')">${x.image?`<img src="${x.image}" alt="${esc(x.id)}" loading="lazy">`:'<div class="placeholder">＋</div>'}${p?`<span class="badge">${t('picked')} ${p.n}</span>`:''}<span class="catb">${esc(catName(x.cat))}</span></div>
    <div class="body"><div class="line"><b class="id">${esc(x.id)}</b><span class="status s-${st}">${stLabel(st)}</span></div>
    <div class="meta"><span class="tag strong">${t('stock')} ${esc(showQty(x)||t('unset'))}</span>${x.size?`<span class="tag">${t('size')} ${esc(x.size)}</span>`:''}${x.base?`<span class="tag">${t('base')} ${esc(x.base)}</span>`:''}</div>
    <div class="qtyrow"><button class="step" onclick="step('${x.key}',-1)">−</button><input id="n-${x.key}" type="number" min="1" ${s>0?`max="${s}"`:''} value="${p?p.n:1}"><button class="step" onclick="step('${x.key}',1)">＋</button></div>
    <div class="action"><button class="add ${p?'selected':''}" onclick="pick('${x.key}')">${p?t('update'):t('add')}</button><button class="btn sm" onclick="detail('${x.key}')">${t('view')}</button></div></div></article>`}).join('')||`<div class="empty wide">${t('noMatch')}${f==='instock'?t('tryAll'):''}</div>`;
  $('#total').textContent=DATA.length;$('#stock').textContent=DATA.filter(inStock).length;$('#ready').textContent=DATA.filter(x=>status(x)==='ok').length;
  update();
}
function step(k,d){const i=$('#n-'+k);i.value=Math.max(1,(parseInt(i.value)||1)+d)}
function pick(k,src){
  const x=byKey(k),inp=$((src||'#n-')+k);let n=Math.max(1,parseInt(inp&&inp.value)||1);const s=stockOf(x);
  if(s!==null&&s>0&&n>s&&!confirm(t('overConfirm')(x.id,s,n)))return;
  const p=picked.find(p=>p.key===k);p?p.n=n:picked.push({key:k,n});saveP();render();toast(`${x.id} × ${n} ${p?t('updated'):t('added')}`);
}
function setN(k,v){const p=picked.find(p=>p.key===k);if(p){p.n=Math.max(1,parseInt(v)||1);saveP();render()}}
function removeP(k){picked=picked.filter(p=>p.key!==k);saveP();render()}
function update(){
  $('#pickedCount').textContent=picked.length;$('#pickedTotal').textContent=picked.reduce((s,p)=>s+p.n,0);
  $('#picked').innerHTML=picked.length?picked.map(p=>{const x=byKey(p.key),s=stockOf(x),over=s!==null&&s>0&&p.n>s;
    return `<div class="picked-item">${x.image?`<img src="${x.image}">`:'<div class="ph"></div>'}<span class="pi"><b>${esc(x.id)}</b><small>${esc(catName(x.cat))} · ${t('stock')} ${esc(showQty(x)||t('unset'))}</small>${over?`<small class="warn">${t('overStock')}</small>`:''}</span><input type="number" min="1" value="${p.n}" onchange="setN('${p.key}',this.value)"><button class="remove" onclick="removeP('${p.key}')">×</button></div>`}).join(''):`<div class="empty">${t('emptyList')}</div>`;
}
function detail(k){const x=byKey(k),p=picked.find(p=>p.key===k),st=status(x);
  $('#detailContent').innerHTML=`<div class="pic big">${x.image?`<img src="${x.image}" alt="${esc(x.id)}">`:'<div class="placeholder">＋</div>'}</div><div class="info"><button class="close" onclick="closeDetail()">×</button><div class="eyebrow dark">${t('detail')}</div><h2>${esc(x.id)}</h2>
  <p>${t('cat')}：${esc(catName(x.cat))}</p><p>${t('stock')}：<b>${esc(showQty(x)||t('unset'))}</b> <span class="status s-${st}">${stLabel(st)}</span></p><p>${t('size')}：${esc(x.size||t('none'))}</p>${x.base?`<p>${t('base')}：${esc(x.base)}</p>`:''}${x.price?`<p>${t('price')}：${esc(x.price)}</p>`:''}
  <div class="qtyrow"><span>${t('qty')}</span><input id="d-${x.key}" type="number" min="1" value="${p?p.n:1}"></div><button class="add selected full" onclick="pick('${x.key}','#d-');closeDetail()">${p?t('update'):t('add')}</button>
  </div>`;
  $('#detail').classList.add('open')}
function closeDetail(){$('#detail').classList.remove('open')}
let tt;function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(tt);tt=setTimeout(()=>e.classList.remove('show'),1800)}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
async function loadImgs(list){await Promise.all(list.filter(x=>x.image&&!x._b64).map(async x=>{try{const b=await (await fetch(x.image)).blob();x._b64=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(b)})}catch(e){}}))}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click()}
const XT='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const BORDER={top:{style:'thin',color:{argb:'FFD0D5DD'}},left:{style:'thin',color:{argb:'FFD0D5DD'}},bottom:{style:'thin',color:{argb:'FFD0D5DD'}},right:{style:'thin',color:{argb:'FFD0D5DD'}}};
function headRow(ws,r,vals){ws.getRow(r).values=vals;ws.getRow(r).eachCell(c=>{c.font={bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF203B68'}};c.alignment={horizontal:'center',vertical:'middle'}});ws.getRow(r).height=22}
function addImg(wb,ws,x,r,size){if(!x._b64)return;const m=x._b64.match(/^data:image\/(\w+);base64,(.*)$/);if(!m)return;const id=wb.addImage({base64:m[2],extension:m[1]==='jpg'?'jpeg':m[1]});ws.addImage(id,{tl:{col:1.08,row:r-1+0.06},ext:{width:size,height:size},editAs:'oneCell'})}
async function exportList(){
  if(!picked.length){alert(t('emptyExport'));return}
  const btn=$('#export');btn.disabled=true;btn.textContent=t('exporting');
  try{await loadImgs(picked.map(p=>byKey(p.key)));const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet(t('listTitle').slice(0,30));const cust=$('#cust').value.trim(),ds=today(),tot=picked.reduce((s,p)=>s+p.n,0);
    ws.columns=[{width:6},{width:20},{width:16},{width:20},{width:10},{width:12},{width:12},{width:20}];
    ws.mergeCells('A1:H1');ws.getCell('A1').value=t('listTitle')+(cust?' - '+cust:'');ws.getCell('A1').font={size:16,bold:true};ws.getCell('A1').alignment={horizontal:'center',vertical:'middle'};ws.getRow(1).height=30;
    ws.mergeCells('A2:H2');ws.getCell('A2').value=`${t('date')}: ${ds}    ${t('styles')}: ${picked.length}    ${t('totalQty')}: ${tot}`;ws.getCell('A2').font={color:{argb:'FF666666'}};
    headRow(ws,3,[t('no'),t('image'),t('code'),t('cat'),t('stock'),t('size'),t('qty'),t('remark')]);
    picked.forEach((p,i)=>{const x=byKey(p.key),r=4+i,s=stockOf(x);const row=ws.getRow(r);
      row.values=[i+1,'',x.id,catName(x.cat),showQty(x),x.size||'',p.n,s!==null&&s>0&&p.n>s?t('overStock'):''];row.height=105;
      row.eachCell({includeEmpty:true},c=>{c.alignment={horizontal:'center',vertical:'middle',wrapText:true};c.border=BORDER});row.getCell(7).font={bold:true};if(row.getCell(8).value)row.getCell(8).font={color:{argb:'FFC0392B'}};addImg(wb,ws,x,r,130)});
    const tr=ws.getRow(4+picked.length);tr.values=['','',t('sum'),'','','',tot,''];tr.font={bold:true};tr.eachCell({includeEmpty:true},c=>{c.alignment={horizontal:'center'};c.border=BORDER});
    ws.views=[{state:'frozen',ySplit:3}];
    download(new Blob([await wb.xlsx.writeBuffer()],{type:XT}),`${t('file')}${cust?'_'+cust:''}_${ds}.xlsx`);toast(t('exported'));
  }catch(e){alert(t('exportFail')+e.message)}finally{btn.disabled=false;btn.textContent=t('export')}
}
/* ---------- init ---------- */
$('#q').oninput=render;$('#filter').onchange=()=>{renderCats();render()};$('#sort').onchange=render;
$('#clear').onclick=()=>{$('#q').value='';$('#filter').value='instock';$('#sort').value='qtydesc';curCat='';renderCats();render()};
$('#clearList').onclick=()=>{if(picked.length&&confirm(t('clearConfirm'))){picked=[];saveP();render()}};
$('#export').onclick=exportList;$('#detail').onclick=e=>{if(e.target.id==='detail')closeDetail()};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDetail()});
document.querySelectorAll('.metric[data-f]').forEach(m=>m.onclick=()=>{$('#filter').value=m.dataset.f;renderCats();render()});
$('#langBtn').onclick=()=>{lang=lang==='en'?'zh':'en';localStorage.setItem('inv_lang',lang);applyLang();if($('#detail').classList.contains('open'))closeDetail()};
applyLang();
